#include <vector>
#include <stack>
using namespace std;

class Solution {
public:
    vector<int> mostCompetitive(vector<int>& nums, int k) {
        stack<int> stk;
        int n = nums.size();

        for (int i = 0; i < n; ++i) {
            while (stk.size() > 0 && stk.top() > nums[i] && stk.size() + (n - i) > k) {
                stk.pop();
            }
            if (stk.size() < k) stk.push(nums[i]);
        }

        vector<int> result(k);
        for (int i = k - 1; i >= 0; --i) {
            result[i] = stk.top();
            stk.pop();
        }

        return result;
    }
};
